CREATE TABLE jp_days ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, starts_on TEXT, ends_on TEXT, atelier_minutes INTEGER NOT NULL DEFAULT 20, transition_minutes INTEGER NOT NULL DEFAULT 5, show_planning INTEGER NOT NULL DEFAULT 1, keypoints_published INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE TABLE jp_ateliers ( id INTEGER PRIMARY KEY AUTOINCREMENT, jp_id INTEGER NOT NULL REFERENCES jp_days(id) ON DELETE CASCADE, code TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, title TEXT, discipline TEXT, author_id INTEGER REFERENCES people(id), reviewer_id INTEGER REFERENCES people(id), status TEXT NOT NULL DEFAULT 'redaction', content TEXT NOT NULL DEFAULT '{}', updated_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE (jp_id, code) );
CREATE TABLE jp_reviews ( id INTEGER PRIMARY KEY AUTOINCREMENT, atelier_id INTEGER NOT NULL REFERENCES jp_ateliers(id) ON DELETE CASCADE, author_name TEXT NOT NULL, stage TEXT, action TEXT NOT NULL, comment TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE TABLE jp_slots ( id INTEGER PRIMARY KEY AUTOINCREMENT, jp_id INTEGER NOT NULL REFERENCES jp_days(id) ON DELETE CASCADE, day TEXT NOT NULL, start_time TEXT NOT NULL, label TEXT, animators TEXT NOT NULL DEFAULT '{}' );
CREATE TABLE jp_participants ( id INTEGER PRIMARY KEY AUTOINCREMENT, jp_id INTEGER NOT NULL REFERENCES jp_days(id) ON DELETE CASCADE, last_name TEXT NOT NULL, first_name TEXT NOT NULL, email TEXT, phone TEXT, faculty TEXT, year TEXT, slot_label TEXT, slot_id INTEGER REFERENCES jp_slots(id) ON DELETE SET NULL, group_no INTEGER, status TEXT NOT NULL DEFAULT 'inscrit', code TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE INDEX idx_jp_ateliers ON jp_ateliers(jp_id);
CREATE INDEX idx_jp_slots ON jp_slots(jp_id);
CREATE INDEX idx_jp_participants ON jp_participants(jp_id);
CREATE INDEX idx_jp_reviews ON jp_reviews(atelier_id);
